changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Italie – Maires et élus régionaux', 'Maires des communes d''au moins 15 000 habitants, présidents, assesseurs et conseillers des Régions, d''après le CSV de l''Anagrafe des administrateurs du ministère de l''Intérieur (catégories IT-1.1 et IT-1.2)', 'it_pep_local_administrators', 'PEP', 'https://dait.interno.gov.it/', 'it-pep-local-administrators', 'D:/test parser 2/plugins/swiftcheck-aml-it-pep-local-administrators-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'OPEN_DATA_FILE', NULL, '{"communesUrl": "https://dait.interno.gov.it/documenti/ammcom.csv", "regionsUrl": "https://dait.interno.gov.it/documenti/ammreg.csv", "minPopulation": "15000"}', 168, 12, 'Données ouvertes du ministère de l''Intérieur : citer la source', 'Ministero dell''Interno, Anagrafe degli amministratori locali e regionali, dait.interno.gov.it', 'Fichier de 31 Mo téléchargé à chaque exécution. Il ne contient que les personnes en fonction : celles qui disparaissent restent publiées 12 mois par la rétention du cœur. Les chefs-lieux de moins de 15 000 habitants s''ajoutent avec le paramètre capoluogoCodes (« province/commune »). Ni diplôme, ni profession, ni liste électorale ne sont repris.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Les 701 maires des communes d''au moins 15 000 habitants, avec date et lieu de naissance et date d''entrée en fonction.', 'Chefs-lieux de moins de 15 000 habitants à ajouter par leur code ; Vallée d''Aoste et Trentin-Haut-Adige hors du fichier ; anciens maires seulement pendant la rétention de 12 mois.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'IT-1.1' AND f.label LIKE 'Maire de chef-lieu%' AND p.dataset_name = 'it_pep_local_administrators';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Les présidents de 17 Régions et leurs 110 assesseurs, avec naissance et date d''entrée en fonction.', 'La Campanie n''a pas de président dans le fichier ; Vallée d''Aoste et Trentin-Haut-Adige absents ; anciens titulaires seulement pendant la rétention de 12 mois.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'IT-1.1' AND f.label LIKE 'Président de Région%' AND p.dataset_name = 'it_pep_local_administrators';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'PARTIAL', FALSE, 'Environ 700 conseillers régionaux (suppléants exclus), avec naissance et date d''entrée en fonction.', 'Vallée d''Aoste et Trentin-Haut-Adige absents ; anciens conseillers seulement pendant la rétention de 12 mois.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'IT-1.2' AND f.label = 'Conseiller régional' AND p.dataset_name = 'it_pep_local_administrators';
